def load(name):
    p = ROOT / "state" / name
    return [json.loads(l) for l in p.read_text(encoding="utf-8").splitlines() if l.strip()]

def append(name, records):
    p = ROOT / "state" / name
    with p.open("a", encoding="utf-8") as fh:
        for r in records:
            fh.write(json.dumps(r, ensure_ascii=False, sort_keys=True) + "\n")

